python3 - <<'EOF'
from pptx import Presentation
p = Presentation("${HOME}/skillpp-recordings/P-V3/slides.pptx")
for i, s in enumerate(p.slides, 1):
    texts = []
    for sh in s.shapes:
        if sh.has_text_frame:
            for para in sh.text_frame.paragraphs:
                t = "".join(r.text for r in para.runs)
                if t.strip():
                    texts.append(t)
    print(f"--- Slide {i} ---")
    for t in texts[:2]:
        print(t)
    print()
EOF
